def _create_caching_extension(
    *,
    mode: SessionMode,
    auto_instantiate: bool,
    config_manager: MarimoConfigManager,
) -> CachingExtension:
    """Create a caching extension configured for the given session mode.

    - EDIT sessions get read-write cache access. Caching is enabled unless
      cells auto-instantiate on startup.
    - RUN sessions get read-only cache access. Caching is enabled only when
      ``serve_cached_sessions_in_apps`` is set in the runtime config.
    """
    if mode == SessionMode.EDIT:
        return CachingExtension(
            enabled=not auto_instantiate,
            mode=CacheMode.READ_WRITE,
        )

    runtime_config = config_manager.get_config().get("runtime", {})
    serve_cached_sessions_in_apps = bool(
        runtime_config.get("serve_cached_sessions_in_apps", False)
    )
    return CachingExtension(
        enabled=serve_cached_sessions_in_apps,
        mode=CacheMode.READ,
    )


